service.method:

		INSERT 
		  INTO SSETL
	         ( HOUSE_CODE
		     , COMPANY_CODE
		     , SMR_NUMBER
		     , SMR_STATUS
		     , ADD_DATE
		     , ADD_TIME
		     , ADD_USER_ID
		     , CHANGE_DATE
		     , CHANGE_TIME
		     , CHANGE_USER_ID
		     , DEL_FLAG
		     , SIGN_STATUS
		     , APPLY_TYPE
		     , SUBJECT
		     , SEAL_USE_TYPE
		     , SUBMISSION_PLACE
		     , ATTACH_NO
		     , REMARK
             , SUBMIT_TYPE
             , SUBMIT_REMARK		     
             , EXT_USE_DETAIL
             , EXT_OUT_EXPECT_DATE
             , EXT_OUT_EXPECT_TIME
             , EXT_IN_EXPECT_DATE
             , EXT_IN_EXPECT_TIME
             , EXT_USE_PLACE
             , EXT_USE_USER_ID 
             , EXT_CPNO_USER_ID
             , EXT_OUT_DATE
             , EXT_OUT_TIME
             , EXT_IN_DATE
             , EXT_IN_TIME
             , EMERGENCY_FLAG
             , EMERGENCY_REMARK
             , ROOT_PATH_TYPE
             , REJECT_REMARK 			 
             , APVID 			 
	         )
	   VALUES( 
	           ${session.HOUSE_CODE}
	         , ${session.COMPANY_CODE}
	         , ${SMR_NUMBER}
	         , 'N'
	         , ${current.DATE}
	         , ${current.TIME}
	         , ${session.ID}
	         , ${current.DATE}
	         , ${current.TIME}
	         , ${session.ID}
	         , 'N'
	         , 'T'
	         , ${APPLY_TYPE}
			 , ${SUBJECT}       
	         , ${SEAL_USE_TYPE}
			 , ${SUBMISSION_PLACE}
			 , ${ATTACH_NO}
			 , ${REMARK}
             , ${SUBMIT_TYPE}
             , ${SUBMIT_REMARK}			 
             , ${EXT_USE_DETAIL}			 
             , ${EXT_OUT_EXPECT_DATE}			 
             , LEFT(CONCAT(#DB_OWNER#NVL(${EXT_OUT_EXPECT_HOUR}, ''), 
             		#DB_OWNER#NVL(${EXT_OUT_EXPECT_MINUTE}, ''), '000000'),6)			 
             , ${EXT_IN_EXPECT_DATE}
             , LEFT(CONCAT(#DB_OWNER#NVL(${EXT_IN_EXPECT_HOUR}, ''), 
             		#DB_OWNER#NVL(${EXT_IN_EXPECT_MINUTE}, ''), '000000'),6)			 
             , ${EXT_USE_PLACE}			 
             , ${EXT_USE_USER_ID} 			 
             , ${EXT_CPNO_USER_ID}
             , ${EXT_OUT_DATE}
             , ${EXT_OUT_TIME}
             , ${EXT_IN_DATE}
             , ${EXT_IN_TIME}
             , ${EMERGENCY_FLAG}
             , ${EMERGENCY_REMARK}
             , ${ROOT_PATH_TYPE}
             , ${REJECT_REMARK} 			 
             , ${APVID} 			 
	       )


DELETE FROM SSETL
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND SMR_NUMBER		= ${SMR_NUMBER}


		SELECT 
			#DB_OWNER#NVL(MAX(SMR_SEQ),0) AS MAXSEQ
  		FROM SSEDC
		WHERE HOUSE_CODE 	= ${session.HOUSE_CODE}
   		AND COMPANY_CODE 	= ${session.COMPANY_CODE}
   		AND SMR_NUMBER 	= ${SMR_NUMBER}


INSERT INTO SSEDC (
	  HOUSE_CODE
	, COMPANY_CODE
	, SMR_NUMBER
	, SMR_SEQ
	, ADD_DATE
	, ADD_TIME
	, ADD_USER_ID
	, DEL_FLAG
	, SEAL_TYPE
	, SUBJECT
	, COUNT
	, ATTACH_NO
	, MANAGE_NUMBER
	, SMD_NUMBER
	, SEAL_MG_USER_ID
	, SEAL_MG_DEPT
	, SEAL_MG_SUBJECT
) VALUES (
	  ${session.HOUSE_CODE  }
	, ${session.COMPANY_CODE}
	, ${SMR_NUMBER          }
	, ${SMR_SEQ             }
	, ${current.DATE        }
	, ${current.TIME        }
	, ${session.ID          }
	, 'N'
	, ${SEAL_TYPE           }
	, ${SUBJECT             }
	, ${COUNT               }
	, ${ATTACH_NO			}
	, ${MANAGE_NUMBER		}
	, ${SMD_NUMBER			}
	, ${SEAL_MG_USER_ID		}
	, ${SEAL_MG_DEPT		}
	, ${SEAL_MG_SUBJECT		}
)


UPDATE SSEDC SET
	  CHANGE_DATE    	= ${current.DATE}
	, CHANGE_TIME    	= ${current.TIME}
	, CHANGE_USER_ID 	= ${session.ID}
	, DEL_FLAG       	= #DB_OWNER#nvl(${DEL_FLAG    }        , DEL_FLAG    )
	, SEAL_TYPE      	= #DB_OWNER#nvl(${SEAL_TYPE   }        , SEAL_TYPE   )
	, SUBJECT        	= #DB_OWNER#nvl(${SUBJECT     }        , SUBJECT     )
	, COUNT          	= #DB_OWNER#nvl(${COUNT       }        , COUNT       )
	, ATTACH_NO        	= #DB_OWNER#nvl(${ATTACH_NO   }        , ATTACH_NO   )
	, ATTACH2_NO        = #DB_OWNER#nvl(${ATTACH2_NO   }       , ATTACH2_NO   )
	, MANAGE_NUMBER   	= #DB_OWNER#nvl(${MANAGE_NUMBER }      , MANAGE_NUMBER  )
	, SMD_NUMBER    	= #DB_OWNER#nvl(${SMD_NUMBER  } 	   , SMD_NUMBER  )
	, SEAL_MG_USER_ID	= #DB_OWNER#nvl(${SEAL_MG_USER_ID  }   , SEAL_MG_USER_ID  )
	, SEAL_MG_DEPT		= #DB_OWNER#nvl(${SEAL_MG_DEPT  }	   , SEAL_MG_DEPT  )
	, SEAL_MG_SUBJECT	= #DB_OWNER#nvl(${SEAL_MG_SUBJECT  }   , SEAL_MG_SUBJECT  )
	, ACCESS_LINK		= #DB_OWNER#nvl(${ACCESS_LINK  }	   , ACCESS_LINK  )
WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
AND COMPANY_CODE 	= ${session.COMPANY_CODE}
AND SMR_NUMBER 		= ${SMR_NUMBER}
AND SMD_NUMBER 		= ${SMD_NUMBER}


DELETE FROM SSEDC
WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
AND COMPANY_CODE 	= ${session.COMPANY_CODE}
AND SMR_NUMBER 		= ${SMR_NUMBER}
AND SMD_NUMBER 		= ${SMD_NUMBER}


INSERT INTO SSEDC_SEAL (
	  HOUSE_CODE
	, COMPANY_CODE
	, SMR_NUMBER
	, SMD_NUMBER
	, MANAGE_NUMBER
	, ADD_DATE
	, ADD_TIME
	, ADD_USER_ID
	, CHANGE_DATE
	, CHANGE_TIME
	, CHANGE_USER_ID 
	, DEL_FLAG
	, MANAGER_ID
	, MANAGE_DEPT
	, ACCEPT_FLAG
	, COMPLETE_FLAG
) VALUES (
	  ${session.HOUSE_CODE  }
	, ${session.COMPANY_CODE}
	, ${SMR_NUMBER          }
	, ${SMD_NUMBER          }
	, ${MANAGE_NUMBER       }
	, ${current.DATE        }
	, ${current.TIME        }
	, ${session.ID          }
	, ${current.DATE        }
	, ${current.TIME        }
	, ${session.ID          }
	, 'N'
	, ${SEAL_MG_USER_ID}
	, ${SEAL_MG_DEPT}
	, 'N'
	, ${COMPLETE_FLAG}
)


UPDATE SSEDC_SEAL SET
	  CHANGE_DATE			= ${current.DATE}
	, CHANGE_TIME			= ${current.TIME}
	, CHANGE_USER_ID		= ${session.ID}
	, DEL_FLAG				= #DB_OWNER#nvl(${DEL_FLAG}, DEL_FLAG)
	, ACCEPT_FLAG			= #DB_OWNER#nvl(${ACCEPT_FLAG}, ACCEPT_FLAG)
	, COMPLETE_FLAG			= #DB_OWNER#nvl(${COMPLETE_FLAG}, COMPLETE_FLAG)
	, MANAGER_ID			= #DB_OWNER#nvl(${MANAGER_ID}, MANAGER_ID)
	, MANAGE_DEPT			= #DB_OWNER#nvl(${MANAGE_DEPT}, MANAGE_DEPT)
	, MANAGE_NUMBER			= #DB_OWNER#nvl(${MANAGE_NUMBER}, MANAGE_NUMBER)
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND SMR_NUMBER		= ${SMR_NUMBER}
AND SMD_NUMBER		= ${SMD_NUMBER}


UPDATE SSEDC_SEAL SET
	  CHANGE_DATE			= ${current.DATE}
	, CHANGE_TIME			= ${current.TIME}
	, CHANGE_USER_ID		= ${session.ID}
	, DEL_FLAG				= #DB_OWNER#nvl(${DEL_FLAG}, DEL_FLAG)
	, ACCEPT_FLAG			= #DB_OWNER#nvl(${ACCEPT_FLAG}, ACCEPT_FLAG)
	, COMPLETE_FLAG			= #DB_OWNER#nvl(${COMPLETE_FLAG}, COMPLETE_FLAG)
	, MANAGER_ID			= #DB_OWNER#nvl(${MANAGER_ID}, MANAGER_ID)
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND SMR_NUMBER		= ${SMR_NUMBER}


DELETE FROM SSEDC_SEAL
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND SMR_NUMBER		= ${SMR_NUMBER}
AND SMD_NUMBER		= ${SMD_NUMBER}


