	, COMPANY_CODE
	, SMR_NUMBER
	, SMI_NUMBER
	, ADD_DATE
	, ADD_TIME
	, ADD_USER_ID
	, DEL_FLAG
	, DOC_TYPE
	, CONTENTS
	, COUNT
) VALUES (
	  ${session.HOUSE_CODE  }
	, ${session.COMPANY_CODE}
	, ${SMR_NUMBER          }
	, ${SMI_NUMBER          }
	, ${current.DATE        }
	, ${current.TIME        }
	, ${session.ID          }
	, 'N'                   
	, ${DOC_TYPE            }
	, ${CONTENTS            }
	, ${COUNT               }
)


DELETE FROM SSISD
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND SMR_NUMBER		= ${SMR_NUMBER}
AND SMI_NUMBER		= ${SMI_NUMBER}


INSERT INTO SSRAD (
	  HOUSE_CODE
	, COMPANY_CODE
	, SMI_NUMBER
	, ADD_DATE
	, ADD_TIME
	, ADD_USER_ID
	, DEL_FLAG
	, SUBJECT
	, CONTENT
	, DOC_TYPE
) VALUES (
	  ${session.HOUSE_CODE  }
	, ${session.COMPANY_CODE}
	, ${SMI_NUMBER          }
	, ${current.DATE        }
	, ${current.TIME        }
	, ${session.ID          }
	, 'N'
	, ${SUBJECT             }
	, ${CONTENT             }
	, ${DOC_TYPE            }
)


UPDATE SSRAD SET
	  CHANGE_DATE		= ${current.DATE}
	, CHANGE_TIME		= ${current.TIME}
	, CHANGE_USER_ID	= ${session.ID}
	, DEL_FLAG			= #DB_OWNER#nvl(${DEL_FLAG}  , DEL_FLAG)
	, SUBJECT			= #DB_OWNER#nvl(${SUBJECT }  , SUBJECT )
	, CONTENT			= #DB_OWNER#nvl(${CONTENT }  , CONTENT )
	, DOC_TYPE			= #DB_OWNER#nvl(${DOC_TYPE}  , DOC_TYPE)
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND SMI_NUMBER		= ${SMI_NUMBER}


DELETE 
FROM SSRAD
WHERE HOUSE_CODE	= ${session.HOUSE_CODE}
AND COMPANY_CODE	= ${session.COMPANY_CODE}
AND SMI_NUMBER		= ${SMI_NUMBER}


SELECT
	HOUSE_CODE
	,COMPANY_CODE
	,USER_ID
FROM
	SUSMT 
WHERE
	HOUSE_CODE = ${HOUSE_CODE}
	AND COMPANY_CODE = ${COMPANY_CODE}
	AND USER_ID = ${USER_ID}


INSERT
  INTO SPMGT
     ( HOUSE_CODE       
      ,COMPANY_CODE     
      ,CONT_NO          
      ,CONT_GL_SEQ      
      ,SEQ              
      ,ADD_DATE         
      ,ADD_TIME         
      ,USER_COMPANY_CODE
      ,USER_ID          
      ,ACTION           
      ,IP
     )
VALUES
     ( ${session.HOUSE_CODE}       
      ,${session.COMPANY_CODE}     
      ,${SMR_NUMBER}        
      ,'1'      
      ,(SELECT COUNT(*) + 1
          FROM SPMGT InPMGT
         WHERE InPMGT.HOUSE_CODE   = ${session.HOUSE_CODE}
           AND InPMGT.COMPANY_CODE = ${session.COMPANY_CODE}
           AND InPMGT.CONT_NO      = ${SMR_NUMBER}
           AND InPMGT.CONT_GL_SEQ  = '1'
       )
      ,${current.DATE}         
      ,${current.TIME}         
      ,${session.COMPANY_CODE}
      ,${session.ID}
      ,${ACTION}           
      ,${IP}
     )


DELETE
  FROM SPMGT
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND CONT_NO      = ${SMR_NUMBER}
   AND CONT_GL_SEQ  = '1'


        INSERT
          INTO SDOIS
             (       
				HOUSE_CODE
			   ,COMPANY_CODE
			   ,ISSUE_NO
			   ,ADD_DATE
			   ,ADD_TIME
			   ,ADD_USER_ID
             )
        VALUES
             ( ${session.HOUSE_CODE}       
              ,${session.COMPANY_CODE}     
              ,${ISSUE_NO}           
              ,${ADD_DATE}
              ,${ADD_TIME}
              ,${session.ID}
             )


    	UPDATE SSETL
		   SET CHANGE_DATE    = ${current.DATE}
	         , CHANGE_TIME    = ${current.TIME}
	         , CHANGE_USER_ID = ${session.ID}
	         , SMR_STATUS     = #DB_OWNER#nvl(${SMR_STATUS		 }  , SMR_STATUS   )
	         , SIGN_DATE      = ${current.DATE}
	         , SIGN_TIME   	  = ${current.TIME}	
	         , SIGN_USER_ID	  = ${session.ID}
	         , REJECT_REMARK  = #DB_OWNER#nvl(${REJECT_REMARK    }  , REJECT_REMARK)
	     WHERE HOUSE_CODE     = ${session.HOUSE_CODE}
	       AND COMPANY_CODE   = ${session.COMPANY_CODE}
	       AND SMR_NUMBER     = ${SMR_NUMBER}


    	UPDATE SSETL
		   SET CHANGE_DATE    = ${current.DATE}
	         , CHANGE_TIME    = ${current.TIME}
	         , CHANGE_USER_ID = ${session.ID}
	         , SMR_STATUS     = #DB_OWNER#nvl(${SMR_STATUS		 }  , SMR_STATUS   )
             , EXT_OUT_DATE   = #DB_OWNER#nvl(${EXT_OUT_EXPECT_DATE  }  , EXT_OUT_EXPECT_DATE  )
             , EXT_OUT_TIME   = LEFT(CONCAT(#DB_OWNER#NVL(${EXT_OUT_EXPECT_HOUR}, ''), 
             		#DB_OWNER#NVL(${EXT_OUT_EXPECT_MINUTE}, ''), '000000'),6)
             , EXT_IN_DATE    = ${current.DATE}
             , EXT_IN_TIME    = ${current.TIME}    	                  	         
	     WHERE HOUSE_CODE     = ${session.HOUSE_CODE}
	       AND COMPANY_CODE   = ${session.COMPANY_CODE}
	       AND SMR_NUMBER     = ${SMR_NUMBER}


    	UPDATE SSETL
		   SET CHANGE_DATE    = ${current.DATE}
	         , CHANGE_TIME    = ${current.TIME}
	         , CHANGE_USER_ID = ${session.ID}
	         , SMR_STATUS     = #DB_OWNER#nvl(${SMR_STATUS		 }  , SMR_STATUS   )
	         , CONFIRM_DATE   = ${current.DATE}
	         , CONFIRM_TIME   = ${current.TIME}	
	         , CONFIRM_USER_ID= ${session.ID}
	     WHERE HOUSE_CODE     = ${session.HOUSE_CODE}
	       AND COMPANY_CODE   = ${session.COMPANY_CODE}
	       AND SMR_NUMBER     = ${SMR_NUMBER}


    	SELECT
			GIVE_USER_ID
		FROM
			SMAND
		WHERE
			HOUSE_CODE = ${session.HOUSE_CODE}
			AND COMPANY_CODE = ${session.COMPANY_CODE}
			AND MAND_TYPE ='01'
			AND RECE_USER_ID =${session.ID}
			AND ${current.DATE} BETWEEN START_DATE AND END_DATE


SELECT SMR_STATUS
     , (SELECT CURRENT_STAGE FROM SGWGL  WHERE HOUSE_CODE = SETL.HOUSE_CODE AND SUX_WKEY1 = SETL.SMR_NUMBER AND APP_STATUS = 'I' AND NVL(DEL_FLAG,'N') = 'N') AS APP_STAGE
 FROM SSETL SETL 
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
  AND COMPANY_CODE = ${session.COMPANY_CODE}
  AND SMR_NUMBER  = ${SMR_NUMBER}
  AND NVL(DEL_FLAG,'N') = 'N'


UPDATE SGWGL 
   SET DEL_FLAG = 'Y' 
 WHERE HOUSE_CODE = ${session.HOUSE_CODE} 
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND SUX_WKEY1 = ${SMR_NUMBER}


SELECT *
FROM SFMFI 
WHERE HOUSE_CODE = ${session.HOUSE_CODE} 
     AND DOC_NUMBER = ${DOC_NUMBER}
     AND LAYER = $S{LAYER}
